import{z as i,x as A,o as r,c,q as E,j as d,D as t,d as o,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"overload 与强制","description":"","frontmatter":{"title":"overload 与强制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overload-coerce.md","filePath":"cs/overload-coerce.md","lastUpdated":1791063341000}'),p={name:"cs/overload-coerce.md"};function B(C,a,f,m,u,h){const l=A("Mermaid");return r(),c("div",null,[a[2]||(a[2]=E('<h1 id="overload-与强制" tabindex="-1">overload 与强制 <a class="header-anchor" href="#overload-与强制" aria-label="Permalink to &quot;overload 与强制&quot;">​</a></h1><div class="epigraph"><p>同一拼写可对应多套声明；隐式转换把实参送到形参类型。决议必须在翻译前选出唯一候选，否则后端看见的类型宽度没有定义。</p><footer>—— 据龙书第 6 章；C++ 标准对重载决议的分层整理</footer></div><p>上一课<a href="/cs/type-inference">类型推导直觉</a>用合一解出最一般类型，并声明重载不在合一内部。本课不重做 occurs check。缺口是<strong>多名一义</strong>与<strong>拓宽</strong>：<code>f</code> 有多条声明、<code>int</code> 可送到 <code>double</code>。要在已绑定的候选集上按类型选一，并插入转换节点。选出之后宽度已知，下一课才能发三地址。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>重载：查找返回候选集，不立即报冲突。决议：按实参类型过滤——精确匹配优于拓宽，拓宽优于经用户转换；仍多条则二义错误。运算符 <code>+</code> 是函数重载的语法糖。缺口是这份偏序，不是再综合一遍单声明表达式。</p><p><span class="marginnote">术语翻译：强制（coercion）就是「编译器替你插的类型转换」——你写 f(3) 而形参是 double，编译器在 AST 里悄悄放一个 Cast 节点把 3 变成 3.0；转换规则由语言规定，发生在编译期，不是运行时行为。</span></p><p>强制（coercion）：语言规定的隐式转换，如 <code>int</code> 到 <code>float</code>。必须写进规则并在 AST 上留下 <code>Cast</code> 节点，否则 IR 会用错 opcode。收窄（<code>double</code> 到 <code>int</code>）通常要求显式，以免悄悄丢精度。字符串与数值之间的「弱类型」强制不在主干。</p><h3 id="决议不是运行时分派" tabindex="-1">决议不是运行时分派 <a class="header-anchor" href="#决议不是运行时分派" aria-label="Permalink to &quot;决议不是运行时分派&quot;">​</a></h3><p>重载在编译期钉死声明。虚方法按对象动态类型跳表是另一机制，本课点名不写 vtable。不要把 <code>f(x)</code> 的重载候选留到运行时。</p><p><span class="marginnote">龙书把类型转换写成语义动作。C++ 重载决议有精确/提升/标准转换/用户定义的层次，本课只借层次直觉，不抄标准附录。Appel 强调插入转换后类型确定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对调用：收集可见的同名函数。用实参类型（上一课已推导或检查）打分。唯一最优则绑定到那条声明，对每个实参插入必要的强制。零候选：无匹配；并列最优：二义。</p>',12)),(r(),d(s,null,{default:t(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%90%8C%E5%90%8D%E5%80%99%E9%80%89%22%5D%20--%3E%20RANK%5B%22%E6%8C%89%E5%8C%B9%E9%85%8D%E5%B1%82%E6%AC%A1%E6%89%93%E5%88%86%22%5D%0A%20%20RANK%20--%3E%20ONE%5B%22%E5%94%AF%E4%B8%80%E6%9C%80%E4%BD%B3%20%2B%20Cast%20%E8%8A%82%E7%82%B9%22%5D%0A%20%20RANK%20--%3E%20AMB%5B%22%E4%BA%8C%E4%B9%89%22%5D%0A%20%20RANK%20--%3E%20NONE%5B%22%E6%97%A0%E5%8C%B9%E9%85%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"可变参数、缺省实参是过滤的附加规则，点名即可。模板/泛型实例化不在本课展开。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[o("每个表达式节点最终一个类型、一个宽度，"),e("a",{href:"/cs/fixed-and-float"},"补码与浮点"),o(" 的运算种类可在 IR 选定。强制可能改变值（整数提升），副作用顺序仍按源。不要在窥孔里偷偷插转换——那是语义，不是优化。")],-1)),a[6]||(a[6]=e("p",null,"打分怎么在一次真实调用上分出胜负：同一实参组合打到几条候选上，层次偏序逐个比下去，剩两条并列才是二义。收窄候选一开始就不参赛。",-1)),(r(),d(s,null,{default:t(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E8%B0%83%E7%94%A8%20f(3%2C%202.5)%22%5D%20--%3E%20A%5B%22%E5%80%99%E9%80%89%20f(int%2C%20double)%22%5D%0A%20%20CALL%20--%3E%20B%5B%22%E5%80%99%E9%80%89%20f(double%2C%20int)%22%5D%0A%20%20CALL%20--%3E%20C%5B%22%E5%80%99%E9%80%89%20f(long%2C%20long)%22%5D%0A%20%20A%20--%3E%20SA%5B%223%20%E7%B2%BE%E7%A1%AE%EF%BC%8C2.5%20%E7%B2%BE%E7%A1%AE%EF%BC%9A%E5%85%A8%E7%B2%BE%E7%A1%AE%E6%9C%80%E4%BC%98%22%5D%0A%20%20B%20--%3E%20SB%5B%223%20%E8%A6%81%E6%8B%93%E5%AE%BD%EF%BC%8C2.5%20%E8%A6%81%E6%94%B6%E7%AA%84%EF%BC%9A%E4%B8%8D%E5%8F%82%E8%B5%9B%22%5D%0A%20%20C%20--%3E%20SC%5B%22%E4%B8%A4%E4%B8%AA%E5%AE%9E%E5%8F%82%E9%83%BD%E9%9D%A0%E8%BD%AC%E6%8D%A2%EF%BC%9A%E6%AC%A1%E4%BC%98%22%5D%0A%20%20SA%20--%3E%20WIN%5B%22%E7%BB%91%E5%AE%9A%E5%AE%83%EF%BC%8C%E6%8F%92%E5%85%A5%E5%BF%85%E8%A6%81%20Cast%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">数字实例：实参 3 送到 double 形参是拓宽，数值一分不丢；反过来 2.9 送到 int 形参会截成 2、丢掉 0.9——收窄必须显式写 (int) 的道理就在这：让丢精度的地方在源码里看得见。</span></p><p><span class="marginnote">常见误区：初学者容易把重载决议与虚方法分派混为一谈。前者在编译期按静态类型选声明，后者在运行期按对象实际类型走跳表；同名调用一个靠类型层次、一个靠 vtable，时机与依据都不同。</span></p><p>与合一：候选选定后，若仍有类型变量，再对那一条声明合一；先选后合一，或对每条尝试合一再打分，语言定一种，本课不并行写两种实现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不生成三地址、不分配寄存器。不处理 ADL、不写完整 C++。后课默认：能进中端的程序，调用与运算符都已钉死声明并插完 Cast。线性 IR 是下一课把树压成 \\(x\\leftarrow y\\,\\mathrm{op}\\,z\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重载在编译期按类型层次选出唯一声明。</li><li>强制显式成 AST 节点，宽度才能进 IR。</li><li>动态分派不是重载。</li><li>出处：Aho et al., 龙书第 6 章。</li></ul>',7))])}const _=i(p,[["render",B]]);export{b as __pageData,_ as default};
